def q(item):
    name,h=item
    u=f"https://{h}/api/v2/help_center/articles/search.json?query=cancel%20subscription&per_page=3"
    try: j=json.loads(subprocess.run(["curl","-s","-m","15","-A","Mozilla/5.0",u],capture_output=True,text=True,timeout=20).stdout)
    except Exception: return None
    for a in j.get("results",[]):
        ti=a.get("title","")
        if not re.search(r"cancel",ti,re.I) or not re.search(r"subscri|member|plan|account|trial|premium|plus|renew",ti,re.I): continue
        if re.search(r"what happens|why|trouble|still|will i|sitter|viewer|insurance|jiobit|google play|app store|apple|android|ios|refund policy|after",ti,re.I): continue
        t=re.sub(r"\s+"," ",html.unescape(re.sub(r"<[^>]+>"," ",a.get("body") or "")))
        s=[x.strip() for x in re.split(r"(?<=[.!?])\s+",t) if 20<len(x)<300][:5]
        if len(s)>=2 and h.split(".")[-2] in a["html_url"]:
            return {"merchant":name,"source_url":a["html_url"],"title":a["title"],"evidence":s}
with ThreadPoolExecutor(16) as ex: r=[x for x in ex.map(q,hosts.items()) if x]
json.dump(r,open("zd2.json","w"),indent=1); print(len(r))
